//! `setup` (M6 step 7, M7 step 12, M8 step 9): the real binary builds a Linux or Windows setup file
//! from a release it packed, and the file is read back the way the runtime reads it (the trailer
//! locator, `SetupTrailer::parse`, then `verify_setup`). For a macOS target it builds a `.zip` of the
//! bundle (any host) or the installer `.dmg` (a macOS host; the cases skip with a printed reason
//! elsewhere).
//! Keys are generated by the binary at test time; every command's output, and the setup file
//! itself, is scanned for every secret generated so far.

#![cfg(unix)]

mod common;

use std::cell::RefCell;
use std::fs;
use std::os::unix::fs::PermissionsExt;
use std::path::{Path, PathBuf};
use std::process::Output;

use common::*;
use ed25519_dalek::SigningKey;
use ed25519_dalek::pkcs8::DecodePrivateKey;
use lunepack_codec_lzma::LzmaCodec;
use lunepack_core::pe::{PeHeaders, PeImage};
use lunepack_core::setup::{
    Located, SetupTrailer, TRAILER_MAGIC, TRAILER_SIZE, locate_file, verify_setup,
};
use lunepack_core::{Clock, ClockReading, FsError, FsErrorKind, ReadAt};
use lunepack_crypto::{Ed25519Verifier, Sha256Hasher};
use lunepack_testkit::exe_headers;

const APP: &str = "org.example.hello";
const T0: u64 = 1_800_000_000;
const AT: u64 = T0 + 3600;
const VERSION: &str = "1.2.3";
const TARGET: &str = "linux-x86_64";

struct At(u64);

impl Clock for At {
    fn now_unix_secs(&self) -> u64 {
        self.0
    }
}

struct Bytes(Vec<u8>);

impl ReadAt for Bytes {
    fn size(&self) -> Result<u64, FsError> {
        Ok(self.0.len() as u64)
    }

    fn read_exact_at(&self, offset: u64, buf: &mut [u8]) -> Result<(), FsError> {
        let start = offset as usize;
        match self.0.get(start..start + buf.len()) {
            Some(src) => {
                buf.copy_from_slice(src);
                Ok(())
            }
            None => Err(FsError::new(FsErrorKind::Other, Path::new("setup"), None)),
        }
    }
}

fn s(path: &Path) -> &str {
    path.to_str().expect("utf-8 path")
}

const UPDATE_TOML: &str = r#"
[update]
feed = "https://updates.example.com/hello"
channel = "stable"
health_timeout_secs = 30

[install]
entry = "bin/app"
name = "Hello"
bin = "hello"
publisher = "Example Org"
"#;

/// A 64-bit little-endian static ELF (one `PT_LOAD`), then filler.
fn runtime_elf(machine: u16) -> Vec<u8> {
    let mut h = exe_headers::elf(machine, false, 64 + 56 + 4096);
    h[16..18].copy_from_slice(&3u16.to_le_bytes());
    h[32..40].copy_from_slice(&64u64.to_le_bytes());
    h[54..56].copy_from_slice(&56u16.to_le_bytes());
    h[56..58].copy_from_slice(&1u16.to_le_bytes());
    h[64..68].copy_from_slice(&1u32.to_le_bytes());
    h
}

/// A config, release keys, and one packed release `1.2.3` for `linux-x86_64` with a runtime.
struct World {
    dir: tempfile::TempDir,
    config: PathBuf,
    release: PathBuf,
    runtime: Vec<u8>,
    /// The target the release was packed for and `setup` builds.
    target: &'static str,
    secrets: RefCell<Vec<Vec<u8>>>,
}

/// What a macOS world differs by: whether the release carries the helper app (`--ui`) and an icon,
/// and whether the bundle was code-signed (ad hoc, at test time) before it was packed.
#[derive(Clone, Copy)]
struct Mac {
    ui: bool,
    icon: bool,
    signed: bool,
    /// Whether the release holds the update service (`--service`, M11): it also gets an
    /// all-users `.pkg`. Only with an unsigned bundle.
    service: bool,
}

/// What a Windows world differs by: the runtime image, extra config, extra input files.
struct Windows {
    runtime: Vec<u8>,
    toml: &'static str,
    /// Files of the input tree.
    files: Vec<(&'static str, Vec<u8>)>,
    /// Files beside the config (a `[windows] icon`).
    beside_config: Vec<(&'static str, Vec<u8>)>,
}

impl World {
    fn new() -> World {
        World::build(None, None)
    }

    fn windows(spec: Windows) -> World {
        World::build(Some(spec), None)
    }

    fn mac(spec: Mac) -> World {
        World::build(None, Some(spec))
    }

    fn build(windows: Option<Windows>, mac: Option<Mac>) -> World {
        let dir = tempfile::tempdir().unwrap();
        let target = if windows.is_some() {
            WIN
        } else if mac.is_some() {
            mac_target()
        } else {
            TARGET
        };
        let w = World {
            config: dir.path().join("lunepack.toml"),
            release: dir.path().join("rel"),
            runtime: match (&windows, &mac) {
                (Some(spec), _) => spec.runtime.clone(),
                (None, Some(_)) => mac_binary(false),
                (None, None) => runtime_elf(62),
            },
            target,
            secrets: RefCell::new(Vec::new()),
            dir,
        };
        let root = w.new_key("root");
        let rel_key = w.new_key("release0");
        assert_ok(
            &w.run(&["init", "--app-id", APP, "--root-key", &root.1], &[]),
            "init",
        );
        {
            use std::io::Write as _;
            let mut f = fs::OpenOptions::new().append(true).open(&w.config).unwrap();
            match (&windows, &mac) {
                (Some(spec), _) => {
                    let toml = UPDATE_TOML.replace("bin/app", "bin/app.exe");
                    f.write_all(toml.as_bytes()).unwrap();
                    f.write_all(spec.toml.as_bytes()).unwrap();
                }
                (None, Some(m)) => {
                    f.write_all(MAC_TOML.as_bytes()).unwrap();
                    if m.icon {
                        f.write_all(b"\n[macos]\nicon = \"app.icns\"\n").unwrap();
                    }
                }
                (None, None) => f.write_all(UPDATE_TOML.as_bytes()).unwrap(),
            }
        }
        fs::create_dir(&w.release).unwrap();
        let root_spec = format!("file:{}", s(&root.0));
        let rel_spec = format!("file:{}", s(&rel_key.0));
        let out = w.run(
            &[
                "keys",
                "set",
                "--release-dir",
                s(&w.release),
                "--threshold",
                "1",
                "--release-key",
                &rel_key.1,
                "--sign",
                &root_spec,
            ],
            &[("SOURCE_DATE_EPOCH", &T0.to_string())],
        );
        assert_ok(&out, "keys set");

        for (rel, bytes) in windows.iter().flat_map(|spec| &spec.beside_config) {
            fs::write(w.dir.path().join(rel), bytes).unwrap();
        }
        if let Some(m) = mac {
            w.pack_mac(m, &rel_spec);
            return w;
        }
        let input = w.dir.path().join("input");
        let entry = input.join(if windows.is_some() {
            "bin/app.exe"
        } else {
            "bin/app"
        });
        fs::create_dir_all(entry.parent().unwrap()).unwrap();
        let entry_bytes = if windows.is_some() {
            exe_headers::pe(0x8664, 8_000)
        } else {
            exe_headers::elf(62, false, 20_000)
        };
        fs::write(&entry, entry_bytes).unwrap();
        fs::set_permissions(&entry, fs::Permissions::from_mode(0o755)).unwrap();
        for (rel, bytes) in windows.iter().flat_map(|spec| &spec.files) {
            let path = input.join(rel);
            fs::create_dir_all(path.parent().unwrap()).unwrap();
            fs::write(path, bytes).unwrap();
        }
        fs::create_dir_all(input.join("data")).unwrap();
        fs::write(input.join("data/readme.txt"), b"read me\n".repeat(400)).unwrap();
        let runtime = w.dir.path().join("runtime");
        fs::write(&runtime, &w.runtime).unwrap();
        let stub = w.dir.path().join("stub.exe");
        fs::write(&stub, hardened(0x8664, 2)).unwrap();
        let tmp = w.dir.path().join("tmp");
        fs::create_dir(&tmp).unwrap();
        let mut pack = vec![
            "pack",
            "--input",
            s(&input),
            "--version",
            VERSION,
            "--target",
            target,
            "--release-dir",
            s(&w.release),
            "--sign",
            &rel_spec,
            "--runtime",
            s(&runtime),
        ];
        if windows.is_some() {
            pack.extend_from_slice(&["--stub", s(&stub)]);
        }
        let out = w.run(
            &pack,
            &[("SOURCE_DATE_EPOCH", &T0.to_string()), ("TMPDIR", s(&tmp))],
        );
        assert_ok(&out, "pack");
        w
    }

    /// Packs release `VERSION` of the macOS bundle (M8): the plain test bundle, or a real one
    /// signed ad hoc, with the runtime and, with `ui`, the helper app's UI.
    fn pack_mac(&self, mac: Mac, rel_spec: &str) {
        let (runtime, ui) = (self.dir.path().join("runtime"), self.dir.path().join("ui"));
        fs::write(&runtime, mac_binary(mac.signed)).unwrap();
        fs::write(&ui, mac_binary(mac.signed)).unwrap();
        assert!(
            !(mac.signed && mac.service),
            "a service is packed unsigned here"
        );
        let service = self.dir.path().join("service");
        fs::write(&service, mac_binary(false)).unwrap();
        if mac.icon {
            fs::write(self.dir.path().join("app.icns"), icns(b"pixels")).unwrap();
        }
        let input = self.dir.path().join("input");
        fs::create_dir(&input).unwrap();
        if mac.signed {
            real_bundle(&input);
        } else {
            mac_bundle(&input);
        }
        let epoch = T0.to_string();
        let tmp = self.dir.path().join("tmp");
        fs::create_dir(&tmp).unwrap();
        let env = [("SOURCE_DATE_EPOCH", epoch.as_str()), ("TMPDIR", s(&tmp))];
        let pack = |input: &Path, runtime: &Path, ui: &Path, extra: &[&str]| {
            let mut args = vec![
                "pack",
                "--input",
                s(input),
                "--version",
                VERSION,
                "--target",
                self.target,
                "--runtime",
                s(runtime),
            ];
            if mac.ui {
                args.extend_from_slice(&["--ui", s(ui)]);
            }
            if mac.service {
                args.extend_from_slice(&["--service", s(&service)]);
            }
            args.extend_from_slice(extra);
            self.run(&args, &env)
        };
        if !mac.signed {
            let out = pack(
                &input,
                &runtime,
                &ui,
                &["--release-dir", s(&self.release), "--sign", rel_spec],
            );
            assert_ok(&out, "pack");
            return;
        }
        // The signed flow of CLI.md: assemble, sign inside out, pack the signed copies as they are.
        let assembled = self.dir.path().join("assembled");
        assert_ok(
            &pack(&input, &runtime, &ui, &["--assemble", s(&assembled)]),
            "assemble",
        );
        let helper = assembled.join("Contents/Helpers/lunepack-update.app");
        let signed_runtime = assembled.join("Contents/MacOS/lunepack-runtime");
        let signed_ui = helper.join("Contents/MacOS/lunepack-ui");
        for code in [&signed_runtime, &signed_ui, &helper, &assembled] {
            codesign(code);
        }
        let out = pack(
            &assembled,
            &signed_runtime,
            &signed_ui,
            &["--release-dir", s(&self.release), "--sign", rel_spec],
        );
        assert_ok(&out, "pack of the signed bundle");
    }

    fn cmd(&self, args: &[&str], env: &[(&str, &str)]) -> Output {
        let output = run(args, env);
        let secrets = self.secrets.borrow();
        let refs: Vec<&[u8]> = secrets.iter().map(Vec::as_slice).collect();
        assert_no_secrets(&output, &refs);
        output
    }

    fn run(&self, args: &[&str], env: &[(&str, &str)]) -> Output {
        let mut full = vec!["--config", s(&self.config)];
        full.extend_from_slice(args);
        self.cmd(&full, env)
    }

    /// A key file and its public key; the secret is remembered for the scans.
    fn new_key(&self, name: &str) -> (PathBuf, String) {
        let base = self.dir.path().join(name);
        let out = self.cmd(&["keys", "gen", s(&base)], &[]);
        assert_ok(&out, "keys gen");
        let path = base.with_extension("key");
        let pem = fs::read_to_string(&path).unwrap();
        let seed = SigningKey::from_pkcs8_pem(&pem).unwrap().to_bytes();
        let mut secrets = self.secrets.borrow_mut();
        secrets.push(pem.into_bytes());
        secrets.push(seed.to_vec());
        (path, field(&stdout(&out), "public:"))
    }

    fn setup(&self, out: &Path, extra: &[&str]) -> Output {
        let at = AT.to_string();
        let mut args = vec![
            "setup",
            s(&self.release),
            "--version",
            VERSION,
            "--target",
            self.target,
            "--out",
            s(out),
            "--at",
            &at,
        ];
        args.extend_from_slice(extra);
        self.run(&args, &[])
    }

    fn release_file(&self, rel: &str) -> PathBuf {
        self.release.join(rel)
    }
}

const WIN: &str = "windows-x86_64";

const ARM64: u32 = 0x0100_000C;
const X86_64: u32 = 0x0100_0007;

/// The macOS target the tests pack for: the host's architecture, so a signed test binary is a
/// runtime for it.
fn mac_target() -> &'static str {
    if cfg!(target_arch = "aarch64") {
        "macos-aarch64"
    } else {
        "macos-x86_64"
    }
}

fn mac_cputype() -> u32 {
    if cfg!(target_arch = "aarch64") {
        ARM64
    } else {
        X86_64
    }
}

const MAC_TOML: &str = r#"
[update]
feed = "https://updates.example.com/hello"
channel = "stable"
health_timeout_secs = 30

[install]
entry = "Contents/MacOS/Hello"
name = "Hello"
publisher = "Example Org"
"#;

/// A Mach-O image for the host's architecture, or, for a bundle that is signed at test time, a
/// real executable (this test binary) that `codesign` accepts.
fn mac_binary(real: bool) -> Vec<u8> {
    if real {
        fs::read(std::env::current_exe().unwrap()).unwrap()
    } else {
        exe_headers::macho(mac_cputype(), false, 4_096)
    }
}

fn write_file(root: &Path, rel: &str, bytes: &[u8], mode: u32) {
    let path = root.join(rel);
    fs::create_dir_all(path.parent().unwrap()).unwrap();
    fs::write(&path, bytes).unwrap();
    fs::set_permissions(&path, fs::Permissions::from_mode(mode)).unwrap();
}

/// A bundle input: an `Info.plist`, the entry, a framework with `Versions/Current` symlinks, an
/// executable helper tool, an empty directory and a name that is not ASCII.
fn mac_bundle(root: &Path) {
    write_file(root, "Contents/Info.plist", b"<plist/>", 0o644);
    write_file(
        root,
        "Contents/MacOS/Hello",
        &exe_headers::macho(mac_cputype(), false, 20_000),
        0o755,
    );
    write_file(
        root,
        "Contents/Resources/readme.txt",
        &b"read me\n".repeat(400),
        0o644,
    );
    write_file(
        root,
        "Contents/Resources/caf\u{e9}.txt",
        b"utf-8 name",
        0o644,
    );
    let fw = "Contents/Frameworks/Foo.framework";
    write_file(
        root,
        &format!("{fw}/Versions/A/Foo"),
        &exe_headers::macho(mac_cputype(), false, 9_000),
        0o755,
    );
    write_file(
        root,
        &format!("{fw}/Versions/A/Resources/Info.plist"),
        b"<plist/>",
        0o644,
    );
    std::os::unix::fs::symlink("A", root.join(format!("{fw}/Versions/Current"))).unwrap();
    // The direct form. FORMAT 10.2 (M8-D20) also accepts the standard `Foo` -> `Versions/Current/Foo`
    // through the link `Versions/Current` -> `A`; the pack test covers that form.
    std::os::unix::fs::symlink("Versions/A/Foo", root.join(format!("{fw}/Foo"))).unwrap();
    write_file(
        root,
        "Contents/Helpers/Updater",
        &b"tool\n".repeat(100),
        0o755,
    );
    fs::create_dir_all(root.join("Contents/Resources/empty")).unwrap();
}

/// A bundle `codesign` can sign: a real `Info.plist` and a real executable.
fn real_bundle(root: &Path) {
    let plist = "<?xml version=\"1.0\" encoding=\"UTF-8\"?>\n\
<!DOCTYPE plist PUBLIC \"-//Apple//DTD PLIST 1.0//EN\" \"http://www.apple.com/DTDs/PropertyList-1.0.dtd\">\n\
<plist version=\"1.0\"><dict>\
<key>CFBundleExecutable</key><string>Hello</string>\
<key>CFBundleIdentifier</key><string>org.example.hello</string>\
<key>CFBundlePackageType</key><string>APPL</string>\
<key>CFBundleName</key><string>Hello</string>\
</dict></plist>\n";
    write_file(root, "Contents/Info.plist", plist.as_bytes(), 0o644);
    write_file(root, "Contents/MacOS/Hello", &mac_binary(true), 0o755);
    write_file(root, "Contents/Resources/readme.txt", b"read me\n", 0o644);
}

/// Signs `path` ad hoc (a test key is never involved), in place.
fn codesign(path: &Path) {
    let out = std::process::Command::new("/usr/bin/codesign")
        .args(["--force", "--sign", "-", "--timestamp=none"])
        .arg(path)
        .output()
        .expect("start codesign");
    assert!(
        out.status.success(),
        "codesign {}: {}",
        path.display(),
        String::from_utf8_lossy(&out.stderr)
    );
}

fn icns(payload: &[u8]) -> Vec<u8> {
    let mut v = b"icns".to_vec();
    v.extend_from_slice(&(8 + payload.len() as u32).to_be_bytes());
    v.extend_from_slice(payload);
    v
}

/// A hardened PE image (M7-D10).
fn hardened(machine: u16, subsystem: u16) -> Vec<u8> {
    exe_headers::pe_image(machine, &exe_headers::PeSpec::hardened(subsystem))
}

/// Parses and verifies `bytes` as the runtime does, at `AT`.
fn check(bytes: &[u8]) -> Result<lunepack_core::setup::VerifiedSetup, String> {
    if (bytes.len() as u64) < TRAILER_SIZE {
        return Err("short".into());
    }
    let tail = &bytes[bytes.len() - TRAILER_SIZE as usize..];
    let trailer = SetupTrailer::parse(tail, bytes.len() as u64, &Sha256Hasher, &Ed25519Verifier)
        .map_err(|e| format!("trailer: {e}"))?;
    verify_setup(
        &trailer,
        &Bytes(bytes.to_vec()),
        &ClockReading::read(&At(AT), None),
        &LzmaCodec,
        &Sha256Hasher,
        &Ed25519Verifier,
    )
    .map_err(|e| format!("payload: {e}"))
}

fn trailer_of(bytes: &[u8]) -> SetupTrailer {
    let tail = &bytes[bytes.len() - TRAILER_SIZE as usize..];
    SetupTrailer::parse(tail, bytes.len() as u64, &Sha256Hasher, &Ed25519Verifier).unwrap()
}

#[test]
fn setup_writes_runtime_payload_and_trailer_deterministically() {
    let w = World::new();
    let a = w.dir.path().join("a-setup");
    let b = w.dir.path().join("b-setup");
    let out = w.setup(&a, &[]);
    assert_ok(&out, "setup");
    assert!(
        stdout(&out).starts_with("setup: a-setup ("),
        "{}",
        stdout(&out)
    );
    assert_ok(&w.setup(&b, &[]), "setup again");
    let bytes = fs::read(&a).unwrap();
    assert_eq!(bytes, fs::read(&b).unwrap(), "two runs differ");
    assert_eq!(
        fs::metadata(&a).unwrap().permissions().mode() & 0o777,
        0o755
    );

    // runtime ‖ key set ‖ manifest ‖ pack ‖ trailer, each part 8-byte aligned.
    assert!(bytes.starts_with(&w.runtime));
    assert!(bytes.ends_with(&TRAILER_MAGIC));
    let t = trailer_of(&bytes);
    let part = |p: lunepack_core::setup::SetupPart| {
        assert_eq!(p.offset % 8, 0);
        bytes[p.offset as usize..(p.offset + p.length) as usize].to_vec()
    };
    assert_eq!(part(t.keys), fs::read(w.release_file("keys.json")).unwrap());
    assert_eq!(
        part(t.manifest),
        fs::read(w.release_file(&format!("{VERSION}/{TARGET}.manifest.json"))).unwrap()
    );
    assert_eq!(
        part(t.pack),
        fs::read(w.release_file(&format!("{VERSION}/{TARGET}.pack"))).unwrap()
    );
    assert!(t.keys.offset >= w.runtime.len() as u64);
    assert_eq!(t.version.to_string(), VERSION);
    assert_eq!(t.target.as_str(), TARGET);
    assert_eq!(t.root.app_id().as_str(), APP);

    let verified = check(&bytes).expect("the setup verifies");
    assert_eq!(verified.config.install.name, "Hello");
    assert_eq!(
        verified.config.install.publisher.as_deref(),
        Some("Example Org")
    );
    assert!(verified.installed_bytes() > 0);

    // No key material: only the public root goes into the file.
    let secrets = w.secrets.borrow();
    let refs: Vec<&[u8]> = secrets.iter().map(Vec::as_slice).collect();
    assert_no_secrets(
        &Output {
            status: out.status,
            stdout: bytes,
            stderr: Vec::new(),
        },
        &refs,
    );
}

#[test]
fn an_existing_output_and_an_unsupported_target_are_refused() {
    let w = World::new();
    let a = w.dir.path().join("a-setup");
    fs::write(&a, b"keep").unwrap();
    let err = assert_fails(&w.setup(&a, &[]), 1, "existing out");
    assert!(err.contains("already exists"), "{err}");
    assert_eq!(fs::read(&a).unwrap(), b"keep");

    // A macOS target the release was not packed for (`--zip`, so it is the release that is
    // missing, on every host).
    let b = w.dir.path().join("b-setup.zip");
    let at = AT.to_string();
    let out = w.run(
        &[
            "setup",
            s(&w.release),
            "--version",
            VERSION,
            "--target",
            "macos-aarch64",
            "--zip",
            "--out",
            s(&b),
            "--at",
            &at,
        ],
        &[],
    );
    let err = assert_fails(&out, 1, "macos target the release lacks");
    assert!(
        err.contains("macos-aarch64.manifest.json does not exist"),
        "{err}"
    );
    assert!(!b.exists());
    // `--zip` is for macOS targets only.
    let out = w.run(
        &[
            "setup",
            s(&w.release),
            "--version",
            VERSION,
            "--target",
            TARGET,
            "--zip",
            "--out",
            s(&b),
            "--at",
            &at,
        ],
        &[],
    );
    let err = assert_fails(&out, 1, "--zip for a Linux target");
    assert!(err.contains("--zip is only for macos-*"), "{err}");
    // A Windows target the release was not packed for.
    let out = w.run(
        &[
            "setup",
            s(&w.release),
            "--version",
            VERSION,
            "--target",
            WIN,
            "--out",
            s(&b),
            "--at",
            &at,
        ],
        &[],
    );
    assert_fails(&out, 1, "windows target of a Linux release");
    assert!(!b.exists());
    // A version the release does not hold.
    let out = w.run(
        &[
            "setup",
            s(&w.release),
            "--version",
            "9.9.9",
            "--target",
            TARGET,
            "--out",
            s(&b),
            "--at",
            &at,
        ],
        &[],
    );
    assert_fails(&out, 1, "absent version");
    assert!(!b.exists());
}

#[test]
fn a_tampered_release_file_is_refused_before_writing() {
    for rel in [
        "keys.json".to_owned(),
        format!("{VERSION}/{TARGET}.manifest.json"),
        format!("{VERSION}/{TARGET}.pack"),
    ] {
        let w = World::new();
        let path = w.release_file(&rel);
        let mut bytes = fs::read(&path).unwrap();
        let mid = bytes.len() / 2;
        bytes[mid] ^= 0x01;
        fs::write(&path, bytes).unwrap();
        let out_path = w.dir.path().join("setup");
        assert_fails(&w.setup(&out_path, &[]), 1, &rel);
        assert!(!out_path.exists(), "{rel}: a file was written");
    }
}

#[test]
fn the_runtime_check_refuses_a_tampered_truncated_or_overlapping_file() {
    let w = World::new();
    let a = w.dir.path().join("a-setup");
    assert_ok(&w.setup(&a, &[]), "setup");
    let bytes = fs::read(&a).unwrap();
    let t = trailer_of(&bytes);

    // One flipped byte in each part.
    for (name, p) in [("keys", t.keys), ("manifest", t.manifest), ("pack", t.pack)] {
        let mut b = bytes.clone();
        b[(p.offset + p.length / 2) as usize] ^= 0x01;
        assert!(check(&b).is_err(), "{name}");
    }
    // Truncated: a byte short, or the trailer gone.
    assert!(check(&bytes[..bytes.len() - 1]).is_err());
    // (The pack's last byte, and the alignment padding after it, are gone.)
    let mut cut = bytes[..(t.pack.offset + t.pack.length - 1) as usize].to_vec();
    cut.extend_from_slice(&bytes[bytes.len() - TRAILER_SIZE as usize..]);
    assert!(check(&cut).is_err(), "a payload byte short");
    // Overlapping parts: the manifest moved into the key set.
    let mut moved = t.clone();
    moved.manifest.offset = t.keys.offset + 8;
    let mut b = bytes[..bytes.len() - TRAILER_SIZE as usize].to_vec();
    b.extend_from_slice(&moved.encode().unwrap());
    let err = check(&b).unwrap_err();
    assert!(err.contains("overlap"), "{err}");
    // A trailer whose root is not the one the config names (another key, same app).
    let other = lunepack_core::TrustedRoot::from_parts(
        t.root.app_id().clone(),
        1,
        1,
        &[[7u8; 32]],
        &Sha256Hasher,
        &Ed25519Verifier,
    );
    if let Ok(other) = other {
        let mut swapped = t.clone();
        swapped.root = other;
        let mut b = bytes[..bytes.len() - TRAILER_SIZE as usize].to_vec();
        b.extend_from_slice(&swapped.encode().unwrap());
        assert!(check(&b).is_err(), "another root");
    }
    // A wrong target in the trailer.
    let mut wrong = t.clone();
    wrong.target = lunepack_core::Target::LinuxAarch64;
    let mut b = bytes[..bytes.len() - TRAILER_SIZE as usize].to_vec();
    b.extend_from_slice(&wrong.encode().unwrap());
    let err = check(&b).unwrap_err();
    assert!(err.contains("target"), "{err}");
    // Untouched, it verifies.
    check(&bytes).unwrap();
}

// ---- Windows setup files (M7 step 12) -------------------------------------------------------

/// `<name> Setup` etc. in the version info of `pe`.
fn version_strings(pe: &[u8]) -> std::collections::BTreeMap<String, String> {
    let image = editpe::Image::parse(pe.to_vec()).unwrap();
    let info = image
        .resource_directory()
        .and_then(|r| r.get_version_info().ok().flatten())
        .expect("a version info");
    info.strings[0]
        .strings
        .iter()
        .map(|(k, v)| (k.clone(), v.clone()))
        .collect()
}

fn icon_png(side: u32) -> Vec<u8> {
    let mut p = b"\x89PNG\r\n\x1a\n".to_vec();
    p.extend_from_slice(&13u32.to_be_bytes());
    p.extend_from_slice(b"IHDR");
    p.extend_from_slice(&side.to_be_bytes());
    p.extend_from_slice(&side.to_be_bytes());
    p.extend_from_slice(&[8, 6, 0, 0, 0, 0, 0, 0, 0]);
    p
}

fn plain_windows() -> Windows {
    Windows {
        runtime: hardened(0x8664, 2),
        toml: "",
        files: Vec::new(),
        beside_config: Vec::new(),
    }
}

/// The runtime copy of a Windows setup file is stamped as the setup variant, keeps every hardening
/// field of the pack's runtime (P3), is checked as a runtime again, and the file reads back as a
/// setup file through the locator, the trailer and `verify_setup`.
#[test]
fn windows_setup_stamps_the_runtime_and_reads_back() {
    let ico = {
        let mut ico = vec![0, 0, 1, 0, 1, 0, 16, 16, 0, 0, 1, 0, 32, 0];
        ico.extend_from_slice(&4u32.to_le_bytes());
        ico.extend_from_slice(&22u32.to_le_bytes());
        ico.extend_from_slice(b"ICON");
        ico
    };
    let w = World::windows(Windows {
        toml: "\n[windows]\nicon = \"app.ico\"\n",
        beside_config: vec![("app.ico", ico)],
        ..plain_windows()
    });
    let out_path = w.dir.path().join("Hello-Setup.exe");
    assert_ok(&w.setup(&out_path, &[]), "windows setup");
    let bytes = fs::read(&out_path).unwrap();

    // Found as a setup file by the locator the runtime uses; nothing follows the trailer.
    let located = locate_file(&Bytes(bytes.clone())).unwrap();
    assert_eq!(
        located,
        Located::Setup {
            end: bytes.len() as u64
        }
    );
    assert!(bytes.ends_with(&TRAILER_MAGIC));
    let verified = check(&bytes).expect("the setup verifies");
    assert_eq!(verified.config.install.name, "Hello");

    // The runtime part: stamped, hardened as the input was, passing the runtime check.
    let t = trailer_of(&bytes);
    let runtime = &bytes[..t.keys.offset as usize];
    lunepack_core::check_runtime_image(runtime, lunepack_core::Target::WindowsX86_64)
        .expect("a hardened Windows runtime");
    let (before, after) = (
        PeImage::parse(&w.runtime).unwrap(),
        PeImage::parse(runtime).unwrap(),
    );
    assert_eq!(after.headers.machine, before.headers.machine);
    assert_eq!(after.headers.subsystem, before.headers.subsystem);
    assert_eq!(after.imports, before.imports);
    assert_eq!(after.delay_imports, before.delay_imports);
    assert_eq!(after.dependent_load_flags, Some(0x800));
    assert_eq!(after.manifest, before.manifest);
    let strings = version_strings(runtime);
    for (key, value) in [
        ("CompanyName", "Example Org"),
        ("FileDescription", "Hello Setup"),
        ("FileVersion", VERSION),
        ("OriginalFilename", "Hello-Setup.exe"),
        ("ProductName", "Hello"),
        ("ProductVersion", VERSION),
    ] {
        assert_eq!(strings.get(key).map(String::as_str), Some(value), "{key}");
    }
    let image = editpe::Image::parse(runtime.to_vec()).unwrap();
    assert!(
        image
            .resource_directory()
            .unwrap()
            .get_main_icon()
            .unwrap()
            .is_some(),
        "the [windows] icon is stamped"
    );
    // Parts are 8-aligned and nothing was appended after the trailer.
    assert_eq!(t.keys.offset % 8, 0);
    assert_eq!(t.target.as_str(), WIN);
    // The default name carries the extension.
    let again = w.dir.path().join("again.exe");
    assert_ok(&w.setup(&again, &[]), "again");
    let strings = version_strings(&fs::read(&again).unwrap());
    assert_eq!(strings["OriginalFilename"], "again.exe");
}

/// F5: signtool zero-pads to 8 before the certificate table, so a setup file whose length is not a
/// multiple of 8 stops ending at its trailer once signed. The writer aligns the trailer: every
/// setup file is a multiple of 8 long, whatever the pack's length (FORMAT.md 14).
#[test]
fn every_setup_file_is_a_multiple_of_8_long() {
    // Incompressible bytes, so the pack's length moves with the file's.
    let noise = |n: usize| -> Vec<u8> {
        let mut x = 0x9E37_79B9_7F4A_7C15_u64;
        (0..n)
            .map(|_| {
                x ^= x << 13;
                x ^= x >> 7;
                x ^= x << 17;
                (x >> 24) as u8
            })
            .collect()
    };
    let mut residues = std::collections::BTreeSet::new();
    let mut lens = Vec::new();
    for extra in 0..8usize {
        let w = World::windows(Windows {
            files: vec![("data/noise.bin", noise(4_000 + extra))],
            ..plain_windows()
        });
        let out_path = w.dir.path().join("s.exe");
        assert_ok(&w.setup(&out_path, &[]), "windows setup");
        let bytes = fs::read(&out_path).unwrap();
        let t = trailer_of(&bytes);
        residues.insert((t.pack.offset + t.pack.length) % 8);
        lens.push(bytes.len());
        // signtool pads to 8 before the table: a multiple of 8 means it adds nothing.
        assert!(
            bytes.len().is_multiple_of(8),
            "setup file {extra} is not 8-aligned"
        );
        assert_eq!(
            locate_file(&Bytes(bytes.clone())).unwrap(),
            Located::Setup {
                end: bytes.len() as u64
            }
        );
    }
    // The inputs did reach unaligned pack ends, so the test would have caught the old writer.
    assert!(
        residues.iter().any(|r| *r != 0),
        "every pack ended 8-aligned: the test proves nothing ({residues:?})"
    );
    // And the Linux file too.
    let w = World::new();
    let out_path = w.dir.path().join("s");
    assert_ok(&w.setup(&out_path, &[]), "linux setup");
    assert!(fs::read(&out_path).unwrap().len().is_multiple_of(8));
}

/// A PNG `install.icon` is read from the pack through its signed frame and stamped; an SVG stamps
/// none.
#[test]
fn windows_setup_reads_a_png_install_icon_from_the_pack() {
    let icon_of = |w: &World| {
        let out_path = w.dir.path().join("s.exe");
        assert_ok(&w.setup(&out_path, &[]), "setup");
        let bytes = fs::read(&out_path).unwrap();
        let t = trailer_of(&bytes);
        let image = editpe::Image::parse(bytes[..t.keys.offset as usize].to_vec()).unwrap();
        image
            .resource_directory()
            .unwrap()
            .get_main_icon()
            .unwrap()
            .map(<[u8]>::to_vec)
    };
    let w = World::windows(Windows {
        toml: "icon = \"assets/icon.png\"\n",
        files: vec![("assets/icon.png", icon_png(64))],
        ..plain_windows()
    });
    let icon = icon_of(&w).expect("an icon");
    assert!(icon.ends_with(&icon_png(64)), "the PNG's bytes, unchanged");

    let w = World::windows(Windows {
        toml: "icon = \"assets/icon.svg\"\n",
        files: vec![("assets/icon.svg", b"<svg/>".to_vec())],
        ..plain_windows()
    });
    assert!(icon_of(&w).is_none());
}

/// A certificate table on the pack's runtime is stripped from the setup file's copy (M7-D11): the
/// file is a setup file whose data ends at its own end, and the stamped copy carries no table.
#[test]
fn windows_setup_strips_a_signed_runtime() {
    let table = vec![0xAB; 64];
    let unsigned = hardened(0x8664, 2);
    let mut spec = exe_headers::PeSpec::hardened(2);
    spec.security_dir = Some((unsigned.len() as u32, table.len() as u32));
    let mut signed = exe_headers::pe_image(0x8664, &spec);
    signed.extend_from_slice(&table);
    let w = World::windows(Windows {
        runtime: signed,
        ..plain_windows()
    });
    let out_path = w.dir.path().join("s.exe");
    assert_ok(&w.setup(&out_path, &[]), "setup");
    let bytes = fs::read(&out_path).unwrap();
    assert_eq!(
        locate_file(&Bytes(bytes.clone())).unwrap(),
        Located::Setup {
            end: bytes.len() as u64
        }
    );
    let t = trailer_of(&bytes);
    let runtime = &bytes[..t.keys.offset as usize];
    let headers = PeHeaders::parse(runtime, runtime.len() as u64).unwrap();
    assert!(headers.security().is_zero(), "the table is gone");
    assert!(
        !runtime.windows(table.len()).any(|w| w == table.as_slice()),
        "its bytes are gone"
    );
    check(&bytes).expect("verifies");
}

/// A certificate table that is not at the end of the runtime's file is refused, and nothing is
/// written.
#[test]
fn windows_setup_refuses_an_odd_certificate_table() {
    let mut spec = exe_headers::PeSpec::hardened(2);
    spec.security_dir = Some((64, 64));
    let mut odd = exe_headers::pe_image(0x8664, &spec);
    odd.extend_from_slice(&[0; 64]);
    let w = World::windows(Windows {
        runtime: odd,
        ..plain_windows()
    });
    let out_path = w.dir.path().join("s.exe");
    let err = assert_fails(&w.setup(&out_path, &[]), 1, "an odd table");
    assert!(err.contains("certificate table"), "{err}");
    assert!(!out_path.exists());
}

// ---- macOS: the `.zip` and the installer `.dmg` (M8 step 9) --------------------------------------

/// What a tree holds at a path.
#[derive(Debug, Clone, PartialEq)]
enum Node {
    Dir,
    File { bytes: Vec<u8>, exec: bool },
    Link(String),
}

/// Every entry under `root` by relative path, nothing followed.
fn tree_of(root: &Path) -> std::collections::BTreeMap<String, Node> {
    fn walk(dir: &Path, prefix: &str, out: &mut std::collections::BTreeMap<String, Node>) {
        for entry in fs::read_dir(dir).unwrap() {
            let entry = entry.unwrap();
            let name = entry.file_name().into_string().unwrap();
            let rel = if prefix.is_empty() {
                name
            } else {
                format!("{prefix}/{name}")
            };
            let path = entry.path();
            let meta = fs::symlink_metadata(&path).unwrap();
            if meta.file_type().is_symlink() {
                let target = fs::read_link(&path).unwrap();
                out.insert(
                    rel,
                    Node::Link(target.into_os_string().into_string().unwrap()),
                );
            } else if meta.is_dir() {
                out.insert(rel.clone(), Node::Dir);
                walk(&path, &rel, out);
            } else {
                let exec = meta.permissions().mode() & 0o111 != 0;
                out.insert(
                    rel,
                    Node::File {
                        bytes: fs::read(&path).unwrap(),
                        exec,
                    },
                );
            }
        }
    }
    let mut out = std::collections::BTreeMap::new();
    walk(root, "", &mut out);
    out
}

fn le16(b: &[u8], at: usize) -> usize {
    u16::from_le_bytes(b[at..at + 2].try_into().unwrap()) as usize
}

fn le32(b: &[u8], at: usize) -> usize {
    u32::from_le_bytes(b[at..at + 4].try_into().unwrap()) as usize
}

/// Reads a zip through its central directory, in an unzipper's way, into a tree relative to
/// `<top>/`; `Err` names the first thing that is not what `lunepack setup --zip` writes.
fn read_zip(zip: &[u8], top: &str) -> std::collections::BTreeMap<String, Node> {
    use std::io::Read as _;
    let end = zip.len() - 22;
    assert_eq!(le32(zip, end), 0x0605_4b50, "end record");
    let count = le16(zip, end + 10);
    let mut at = le32(zip, end + 16);
    let mut out = std::collections::BTreeMap::new();
    let mut seen = Vec::new();
    for _ in 0..count {
        assert_eq!(le32(zip, at), 0x0201_4b50);
        assert_eq!(le16(zip, at + 4) >> 8, 3, "made by Unix");
        let method = le16(zip, at + 10);
        let (csize, size) = (le32(zip, at + 20), le32(zip, at + 24));
        let name_len = le16(zip, at + 28);
        let mode = le32(zip, at + 38) >> 16;
        let local = le32(zip, at + 42);
        let name = String::from_utf8(zip[at + 46..at + 46 + name_len].to_vec()).unwrap();
        at += 46 + name_len;
        let body = local + 30 + le16(zip, local + 26) + le16(zip, local + 28);
        let packed = &zip[body..body + csize];
        let bytes = match method {
            0 => packed.to_vec(),
            8 => {
                let mut v = Vec::new();
                flate2::read::DeflateDecoder::new(packed)
                    .read_to_end(&mut v)
                    .unwrap();
                v
            }
            m => panic!("method {m}"),
        };
        assert_eq!(bytes.len(), size, "{name}");
        seen.push(name.clone());
        let rel = if name == format!("{top}/") {
            continue;
        } else {
            name.strip_prefix(&format!("{top}/"))
                .unwrap_or_else(|| panic!("{name} is outside {top}/"))
                .trim_end_matches('/')
                .to_owned()
        };
        let node = match mode & 0o170_000 {
            0o040_000 => Node::Dir,
            0o120_000 => Node::Link(String::from_utf8(bytes).unwrap()),
            0o100_000 => Node::File {
                bytes,
                exec: mode & 0o111 != 0,
            },
            other => panic!("{name}: file type {other:o}"),
        };
        assert!(out.insert(rel, node).is_none(), "{name} twice");
    }
    assert_eq!(
        seen.first().map(String::as_str),
        Some(format!("{top}/").as_str())
    );
    out
}

/// Checks `got` against the tree the release was packed from: the input bundle, plus what `pack`
/// placed (the runtime, the config and, with a UI, the helper app). A signed bundle was packed as
/// it was assembled and signed, so its tree is the whole oracle.
fn check_released_tree(
    w: &World,
    mac: Mac,
    mut got: std::collections::BTreeMap<String, Node>,
    what: &str,
) {
    let dir = if mac.signed { "assembled" } else { "input" };
    let want = tree_of(&w.dir.path().join(dir));
    if !mac.signed {
        let exe = |bytes: Vec<u8>| Node::File { bytes, exec: true };
        assert_eq!(
            got.remove("Contents/MacOS/lunepack-runtime"),
            Some(exe(mac_binary(false))),
            "{what}: the runtime"
        );
        let config = got.remove("Contents/Resources/lunepack-update.json");
        assert!(
            matches!(&config, Some(Node::File { exec: false, bytes })
                if lunepack_core::UpdateConfig::parse(bytes).is_ok()),
            "{what}: the config"
        );
        if mac.ui {
            let helper = "Contents/Helpers/lunepack-update.app";
            assert_eq!(
                got.remove(&format!("{helper}/Contents/MacOS/lunepack-ui")),
                Some(exe(mac_binary(false))),
                "{what}: the UI"
            );
            let plist = got.remove(&format!("{helper}/Contents/Info.plist"));
            assert!(
                matches!(&plist, Some(Node::File { exec: false, .. })),
                "{what}: the helper's Info.plist"
            );
            if mac.icon {
                let icon = got.remove(&format!("{helper}/Contents/Resources/lunepack-update.icns"));
                let want_icon = Node::File {
                    bytes: icns(b"pixels"),
                    exec: false,
                };
                assert_eq!(icon, Some(want_icon), "{what}: the icon");
            }
            for dir in ["", "/Contents", "/Contents/MacOS", "/Contents/Resources"] {
                got.remove(&format!("{helper}{dir}"));
            }
        }
    }
    assert_eq!(got, want, "{what}: the released tree");
}

/// Extracts `zip` with `tool` into a new directory under `into` and returns the app's directory.
/// `None` (with the reason printed) when the tool is not on this host.
fn extract(tool: &str, zip: &Path, into: &Path) -> Option<PathBuf> {
    let dir = into.join(format!("extracted-{tool}"));
    fs::create_dir(&dir).unwrap();
    let found = |name: &str| {
        ["/usr/bin", "/bin", "/usr/local/bin"]
            .iter()
            .any(|d| Path::new(d).join(name).exists())
    };
    if !found(tool) {
        eprintln!("skipped: {tool} is not on this host");
        return None;
    }
    let mut cmd = std::process::Command::new(tool);
    match tool {
        "ditto" => cmd.args(["-x", "-k"]).arg(zip).arg(&dir),
        _ => cmd.arg("-q").arg(zip).arg("-d").arg(&dir),
    };
    let out = cmd.output().unwrap();
    assert!(
        out.status.success(),
        "{tool}: {}",
        String::from_utf8_lossy(&out.stderr)
    );
    Some(dir.join("Hello.app"))
}

fn mac_zip(w: &World, out: &Path) -> Output {
    let at = AT.to_string();
    w.run(
        &[
            "setup",
            s(&w.release),
            "--version",
            VERSION,
            "--target",
            w.target,
            "--zip",
            "--out",
            s(out),
            "--at",
            &at,
        ],
        &[],
    )
}

const PLAIN_MAC: Mac = Mac {
    ui: true,
    icon: true,
    signed: false,
    service: false,
};

#[test]
fn macos_zip_is_deterministic_and_holds_the_released_bundle() {
    let w = World::mac(PLAIN_MAC);
    let a = w.dir.path().join("a.zip");
    let b = w.dir.path().join("b.zip");
    let out = mac_zip(&w, &a);
    assert_ok(&out, "setup --zip");
    assert!(
        stdout(&out).starts_with("setup: a.zip ("),
        "{}",
        stdout(&out)
    );
    assert_ok(&mac_zip(&w, &b), "setup --zip again");
    let bytes = fs::read(&a).unwrap();
    assert_eq!(bytes, fs::read(&b).unwrap(), "two runs differ");

    // Entries are sorted, the bundle's directory first, and the tree is the released one.
    let tree = read_zip(&bytes, "Hello.app");
    check_released_tree(&w, PLAIN_MAC, tree.clone(), "own reader");
    assert_eq!(
        tree["Contents/Frameworks/Foo.framework/Versions/Current"],
        Node::Link("A".into())
    );
    assert_eq!(
        tree["Contents/Frameworks/Foo.framework/Foo"],
        Node::Link("Versions/A/Foo".into())
    );
    assert!(matches!(
        tree["Contents/MacOS/Hello"],
        Node::File { exec: true, .. }
    ));
    assert!(matches!(
        tree["Contents/Resources/caf\u{e9}.txt"],
        Node::File { exec: false, .. }
    ));
    assert_eq!(tree["Contents/Resources/empty"], Node::Dir);

    // The system's unzippers read it to the same tree (exec bits, link targets).
    for tool in ["unzip", "ditto"] {
        if let Some(app) = extract(tool, &a, w.dir.path()) {
            check_released_tree(&w, PLAIN_MAC, tree_of(&app), tool);
        }
    }
    // Nothing else is written next to the output, and the output holds no secret.
    let names: Vec<String> = fs::read_dir(w.dir.path())
        .unwrap()
        .map(|e| e.unwrap().file_name().into_string().unwrap())
        .filter(|n| n.starts_with(".lunepack-"))
        .collect();
    assert!(names.is_empty(), "{names:?}");
    let secrets = w.secrets.borrow();
    let refs: Vec<&[u8]> = secrets.iter().map(Vec::as_slice).collect();
    assert_no_secrets(
        &Output {
            status: out.status,
            stdout: bytes,
            stderr: Vec::new(),
        },
        &refs,
    );
}

#[test]
fn macos_zip_needs_no_ui_and_no_icon_and_never_replaces_a_file() {
    let mac = Mac {
        ui: false,
        icon: false,
        signed: false,
        service: false,
    };
    let w = World::mac(mac);
    let a = w.dir.path().join("a.zip");
    assert_ok(&mac_zip(&w, &a), "setup --zip of a release without --ui");
    check_released_tree(
        &w,
        mac,
        read_zip(&fs::read(&a).unwrap(), "Hello.app"),
        "no ui",
    );
    let before = fs::read(&a).unwrap();
    let err = assert_fails(&mac_zip(&w, &a), 1, "existing zip");
    assert!(err.contains("already exists"), "{err}");
    assert_eq!(fs::read(&a).unwrap(), before);

    // The default name, in the current directory.
    let cwd = tempfile::tempdir().unwrap();
    let at = AT.to_string();
    let out = run_in(
        Some(cwd.path()),
        &[
            "--config",
            s(&w.config),
            "setup",
            s(&w.release),
            "--version",
            VERSION,
            "--target",
            w.target,
            "--zip",
            "--at",
            &at,
        ],
        &[],
    );
    assert_ok(&out, "default name");
    let expected = format!("{APP}-{VERSION}-{}.zip", w.target);
    assert!(cwd.path().join(&expected).is_file(), "{expected}");
    assert_eq!(fs::read(cwd.path().join(&expected)).unwrap(), before);
}

#[test]
fn macos_zip_of_a_tampered_pack_is_refused_and_leaves_nothing() {
    let w = World::mac(PLAIN_MAC);
    let pack = w.release_file(&format!("{VERSION}/{}.pack", w.target));
    let mut bytes = fs::read(&pack).unwrap();
    let mid = bytes.len() / 2;
    bytes[mid] ^= 0xFF;
    fs::write(&pack, bytes).unwrap();
    let out_dir = tempfile::tempdir().unwrap();
    let a = out_dir.path().join("a.zip");
    let err = assert_fails(&mac_zip(&w, &a), 1, "tampered pack");
    assert!(err.contains("does not match the manifest"), "{err}");
    assert_eq!(fs::read_dir(out_dir.path()).unwrap().count(), 0);
}

/// Skips a case that needs a macOS host, printing why.
fn macos_host(what: &str) -> bool {
    if cfg!(target_os = "macos") {
        true
    } else {
        eprintln!("skipped: {what} needs a macOS host (hdiutil, codesign)");
        false
    }
}

#[test]
fn a_signed_bundle_zipped_and_extracted_still_verifies() {
    if !macos_host("the signed-bundle zip") {
        return;
    }
    let mac = Mac {
        ui: true,
        icon: true,
        signed: true,
        service: false,
    };
    let w = World::mac(mac);
    let a = w.dir.path().join("signed.zip");
    assert_ok(&mac_zip(&w, &a), "setup --zip of a signed bundle");
    let tree = read_zip(&fs::read(&a).unwrap(), "Hello.app");
    assert!(tree.contains_key("Contents/_CodeSignature/CodeResources"));
    check_released_tree(&w, mac, tree, "signed, own reader");
    for tool in ["ditto", "unzip"] {
        let app = extract(tool, &a, w.dir.path()).expect("macOS has the tool");
        check_released_tree(&w, mac, tree_of(&app), tool);
        let out = std::process::Command::new("/usr/bin/codesign")
            .args(["--verify", "--deep", "--strict"])
            .arg(&app)
            .output()
            .unwrap();
        assert!(
            out.status.success(),
            "codesign --verify after {tool}: {}",
            String::from_utf8_lossy(&out.stderr)
        );
    }
}

/// A mounted image, detached when dropped.
struct Mounted(PathBuf);

impl Drop for Mounted {
    fn drop(&mut self) {
        let _ = std::process::Command::new("/usr/bin/hdiutil")
            .args(["detach", "-force"])
            .arg(&self.0)
            .output();
    }
}

fn attach(dmg: &Path, at: &Path) -> Mounted {
    fs::create_dir(at).unwrap();
    let out = std::process::Command::new("/usr/bin/hdiutil")
        .args([
            "attach",
            "-readonly",
            "-nobrowse",
            "-noverify",
            "-noautoopen",
            "-mountpoint",
        ])
        .arg(at)
        .arg(dmg)
        .output()
        .unwrap();
    assert!(
        out.status.success(),
        "hdiutil attach: {}",
        String::from_utf8_lossy(&out.stderr)
    );
    Mounted(at.to_path_buf())
}

fn mac_dmg(w: &World, out: &Path) -> Output {
    let at = AT.to_string();
    w.run(
        &[
            "setup",
            s(&w.release),
            "--version",
            VERSION,
            "--target",
            w.target,
            "--out",
            s(out),
            "--at",
            &at,
        ],
        &[],
    )
}

#[test]
fn macos_dmg_mounts_read_only_and_holds_exactly_the_installer_app() {
    let w = World::mac(PLAIN_MAC);
    let dmg = w.dir.path().join("hello.dmg");
    if !macos_host("the installer .dmg") {
        let err = assert_fails(&mac_dmg(&w, &dmg), 1, "dmg off macOS");
        assert!(err.contains("--zip"), "{err}");
        assert!(!dmg.exists());
        return;
    }
    let out = mac_dmg(&w, &dmg);
    assert_ok(&out, "setup");
    assert!(
        stdout(&out).starts_with("setup: hello.dmg ("),
        "{}",
        stdout(&out)
    );

    let info = std::process::Command::new("/usr/bin/hdiutil")
        .args(["imageinfo", "-plist"])
        .arg(&dmg)
        .output()
        .unwrap();
    assert!(String::from_utf8_lossy(&info.stdout).contains("<string>ULMO</string>"));
    let verify = std::process::Command::new("/usr/bin/hdiutil")
        .arg("verify")
        .arg(&dmg)
        .output()
        .unwrap();
    assert!(verify.status.success());

    let mount = attach(&dmg, &w.dir.path().join("mnt"));
    let root = &mount.0;
    let names: Vec<String> = fs::read_dir(root)
        .unwrap()
        .map(|e| e.unwrap().file_name().into_string().unwrap())
        .filter(|n| !n.starts_with('.'))
        .collect();
    assert_eq!(
        names,
        ["Install Hello.app"],
        "the image holds exactly the installer app"
    );
    assert!(
        fs::write(root.join("probe"), b"x").is_err(),
        "mounted read-only"
    );

    let app = root.join("Install Hello.app");
    // No extended attribute (quarantine, provenance) is carried into the image (M8-D10).
    let xattrs = std::process::Command::new("/usr/bin/xattr")
        .arg("-lr")
        .arg(&app)
        .output()
        .unwrap();
    assert!(xattrs.status.success());
    assert_eq!(
        String::from_utf8_lossy(&xattrs.stdout),
        "",
        "the installer app carries extended attributes"
    );
    let tree = tree_of(&app);
    let files: Vec<&str> = tree
        .iter()
        .filter(|(_, n)| matches!(n, Node::File { .. }))
        .map(|(p, _)| p.as_str())
        .collect();
    assert_eq!(
        files,
        [
            "Contents/Info.plist",
            "Contents/MacOS/lunepack-runtime",
            "Contents/MacOS/lunepack-ui",
            "Contents/Resources/lunepack-installer.icns",
            "Contents/Resources/lunepack-setup.payload",
        ]
    );
    assert!(tree.values().all(|n| !matches!(n, Node::Link(_))));
    let file = |p: &str| match &tree[p] {
        Node::File { bytes, exec } => (bytes.clone(), *exec),
        other => panic!("{p}: {other:?}"),
    };
    assert_eq!(
        file("Contents/MacOS/lunepack-ui"),
        (mac_binary(false), true)
    );
    assert_eq!(
        file("Contents/MacOS/lunepack-runtime"),
        (mac_binary(false), true)
    );
    assert_eq!(
        file("Contents/Resources/lunepack-installer.icns"),
        (icns(b"pixels"), false)
    );
    let (plist, exec) = file("Contents/Info.plist");
    assert!(!exec);
    let plist = String::from_utf8(plist).unwrap();
    for needle in [
        "<key>CFBundleExecutable</key>\n\t<string>lunepack-ui</string>",
        "<string>org.example.hello.lunepack-installer</string>",
        "<key>CFBundleName</key>\n\t<string>Install Hello</string>",
        "<key>CFBundleIconFile</key>\n\t<string>lunepack-installer</string>",
    ] {
        assert!(plist.contains(needle), "{needle}\n{plist}");
    }

    // The payload file is read as the installer's runtime reads it, and verifies.
    let (payload, exec) = file("Contents/Resources/lunepack-setup.payload");
    assert!(!exec);
    assert_eq!(payload.len() % 8, 0);
    let bytes = Bytes(payload.clone());
    let trailer = lunepack_core::setup::parse_payload_file(&bytes, &Sha256Hasher, &Ed25519Verifier)
        .expect("the payload file parses");
    assert_eq!(trailer.keys.offset, 0);
    assert_eq!(trailer.version.to_string(), VERSION);
    assert_eq!(trailer.target.as_str(), w.target);
    let verified = verify_setup(
        &trailer,
        &bytes,
        &ClockReading::read(&At(AT), None),
        &LzmaCodec,
        &Sha256Hasher,
        &Ed25519Verifier,
    )
    .expect("the payload verifies");
    assert_eq!(verified.config.install.name, "Hello");
    let part = |p: lunepack_core::setup::SetupPart| {
        payload[p.offset as usize..(p.offset + p.length) as usize].to_vec()
    };
    assert_eq!(
        part(trailer.keys),
        fs::read(w.release_file("keys.json")).unwrap()
    );
    assert_eq!(
        part(trailer.pack),
        fs::read(w.release_file(&format!("{VERSION}/{}.pack", w.target))).unwrap()
    );
}

#[test]
fn macos_dmg_refusals_leave_nothing_behind() {
    if !macos_host("the installer .dmg") {
        return;
    }
    // A release without the UI has no installer app.
    let w = World::mac(Mac {
        ui: false,
        icon: false,
        signed: false,
        service: false,
    });
    let out_dir = tempfile::tempdir().unwrap();
    let dmg = out_dir.path().join("hello.dmg");
    let err = assert_fails(&mac_dmg(&w, &dmg), 1, "release without --ui");
    assert!(err.contains("--ui") && err.contains("--zip"), "{err}");
    assert_eq!(fs::read_dir(out_dir.path()).unwrap().count(), 0);

    // The image's name must end in .dmg; an existing file is never replaced.
    let w = World::mac(PLAIN_MAC);
    let err = assert_fails(
        &mac_dmg(&w, &out_dir.path().join("hello.img")),
        1,
        "bad extension",
    );
    assert!(err.contains(".dmg"), "{err}");
    fs::write(&dmg, b"keep").unwrap();
    let err = assert_fails(&mac_dmg(&w, &dmg), 1, "existing image");
    assert!(err.contains("already exists"), "{err}");
    assert_eq!(fs::read(&dmg).unwrap(), b"keep");
    let names: Vec<String> = fs::read_dir(out_dir.path())
        .unwrap()
        .map(|e| e.unwrap().file_name().into_string().unwrap())
        .collect();
    assert_eq!(names, ["hello.dmg"]);

    // A tampered pack: refused before any image is made.
    let pack = w.release_file(&format!("{VERSION}/{}.pack", w.target));
    let mut bytes = fs::read(&pack).unwrap();
    let mid = bytes.len() / 2;
    bytes[mid] ^= 0xFF;
    fs::write(&pack, bytes).unwrap();
    let other = out_dir.path().join("other.dmg");
    let err = assert_fails(&mac_dmg(&w, &other), 1, "tampered pack");
    assert!(err.contains("does not match the manifest"), "{err}");
    assert!(!other.exists());
}

// ---- OS signing of the installers (M9 step 4) ---------------------------------------------------

/// The helper programs of one signing test: `sh` scripts in `tools/` that log what they were asked
/// to sign (to `log`) and rewrite it into a form the signed-form checks accept.
struct Tools {
    dir: PathBuf,
    log: PathBuf,
}

impl Tools {
    fn new(w: &World) -> Tools {
        let dir = w.dir.path().join("tools");
        fs::create_dir(&dir).unwrap();
        fs::write(dir.join("signed.macho"), signed_macho()).unwrap();
        Tools {
            log: dir.join("log"),
            dir,
        }
    }

    /// A TOML template running script `name` (body `body`) with the arguments `args`.
    fn template(&self, name: &str, body: &str, args: &[&str]) -> String {
        let path = self.dir.join(format!("{name}.sh"));
        fs::write(
            &path,
            format!(
                "#!/bin/sh\nLOG='{}'\nTOOLS='{}'\n{body}\n",
                self.log.display(),
                self.dir.display()
            ),
        )
        .unwrap();
        let mut parts = vec!["/bin/sh".to_owned(), path.display().to_string()];
        parts.extend(args.iter().map(|a| (*a).to_owned()));
        let items: Vec<String> = parts.iter().map(|p| format!("'{p}'")).collect();
        format!("[{}]", items.join(", "))
    }

    fn log(&self) -> Vec<String> {
        fs::read_to_string(&self.log)
            .unwrap_or_default()
            .lines()
            .map(str::to_owned)
            .collect()
    }

    /// `[codesign.macos]` with fake tools; `over` replaces the body of the tool named by its key
    /// (`sign_installer`, `verify`, `notarize`, `staple`). `sign` always fails: the installer
    /// never uses it.
    fn macos_section(&self, over: &[(&str, &str)]) -> String {
        let body = |key: &str, default: &'static str| -> String {
            over.iter()
                .find(|(k, _)| *k == key)
                .map_or_else(|| default.to_owned(), |(_, b)| (*b).to_owned())
        };
        let sign = self.template("sign", "echo \"sign|$1\" >> \"$LOG\"; exit 9", &["{path}"]);
        let installer = self.template(
            "sign_installer",
            &body(
                "sign_installer",
                "echo \"sign_installer|$(basename \"$1\")\" >> \"$LOG\"\n\
                 case \"$1\" in\n\
                 *.dmg) /usr/bin/codesign --force --sign - \"$1\" ;;\n\
                 *.app) mkdir -p \"$1/Contents/_CodeSignature\"; echo seal > \"$1/Contents/_CodeSignature/CodeResources\" ;;\n\
                 *) cp \"$TOOLS/signed.macho\" \"$1\" ;;\n\
                 esac",
            ),
            &["{path}"],
        );
        let verify = self.template(
            "verify",
            &body("verify", "echo \"verify|$(basename \"$1\")\" >> \"$LOG\""),
            &["{path}"],
        );
        let notarize = self.template(
            "notarize",
            &body(
                "notarize",
                "echo \"notarize|$(basename \"$1\")|$(basename \"$2\")\" >> \"$LOG\"\n\
                 case \"$2\" in *.zip) cp \"$2\" \"$TOOLS/notarized-app.zip\" ;; esac",
            ),
            &["{bundle}", "{zip}"],
        );
        let staple = self.template(
            "staple",
            &body(
                "staple",
                "echo \"staple|$(basename \"$1\")\" >> \"$LOG\"\n\
                 case \"$1\" in\n\
                 *.dmg) ;;\n\
                 *) if [ -e \"$(dirname \"$(dirname \"$1\")\")/installer.dmg\" ]; then echo dmg-existed-before-app-staple >> \"$LOG\"; fi\n\
                    echo ticket > \"$1/Contents/CodeResources\" ;;\n\
                 esac",
            ),
            &["{path}"],
        );
        format!(
            "\n[codesign.macos]\nsign = {sign}\nsign_installer = {installer}\nverify = {verify}\n\
             notarize = {notarize}\nstaple = {staple}\n"
        )
    }
}

fn append_config(w: &World, text: &str) {
    use std::io::Write as _;
    let mut f = fs::OpenOptions::new().append(true).open(&w.config).unwrap();
    f.write_all(text.as_bytes()).unwrap();
}

/// A thin arm64 Mach-O with a code signature the signed-form check accepts.
fn signed_macho() -> Vec<u8> {
    let mut b = Vec::new();
    for word in [0xFEED_FACFu32, ARM64, 0, 2, 1, 16, 0, 0] {
        b.extend_from_slice(&word.to_le_bytes());
    }
    for word in [0x1du32, 16, 64, 16] {
        b.extend_from_slice(&word.to_le_bytes());
    }
    b.resize(80, 0xAA);
    b
}

/// What a signing tool does to a finished PE: a certificate table of 32 bytes at its end.
fn with_certificate_table(bytes: &[u8]) -> Vec<u8> {
    assert_eq!(
        bytes.len() % 8,
        0,
        "a setup file's length is a multiple of 8"
    );
    let at = |b: &[u8], o: usize| u32::from_le_bytes(b[o..o + 4].try_into().unwrap()) as usize;
    let pe = at(bytes, 0x3C);
    let magic = u16::from_le_bytes(bytes[pe + 24..pe + 26].try_into().unwrap());
    let dir = pe + 24 + if magic == 0x20b { 112 } else { 96 } + 4 * 8;
    let mut out = bytes.to_vec();
    out[dir..dir + 4].copy_from_slice(&(bytes.len() as u32).to_le_bytes());
    out[dir + 4..dir + 8].copy_from_slice(&32u32.to_le_bytes());
    out.extend_from_slice(&[0x5A; 32]);
    out
}

/// The entries of `dir`: nothing is left in the output directory but what the test put there.
fn names_in(dir: &Path) -> Vec<String> {
    let mut names: Vec<String> = fs::read_dir(dir)
        .unwrap()
        .map(|e| e.unwrap().file_name().into_string().unwrap())
        .collect();
    names.sort();
    names
}

/// A Windows setup file is signed with `sign_installer` after it is complete, then read back as
/// signed: the locator finds the trailer before the certificate table (M7-D11). A tool that signs
/// nothing, one that damages the trailer and one that appends past the table each stop `setup`
/// with no output file.
#[test]
fn windows_setup_is_signed_and_read_back_as_signed() {
    let w = World::windows(plain_windows());
    let tools = Tools::new(&w);
    let unsigned_dir = w.dir.path().join("unsigned");
    fs::create_dir(&unsigned_dir).unwrap();
    let unsigned_path = unsigned_dir.join("Hello-Setup.exe");
    assert_ok(&w.setup(&unsigned_path, &[]), "unsigned setup");
    let unsigned = fs::read(&unsigned_path).unwrap();
    let signed = with_certificate_table(&unsigned);
    fs::write(tools.dir.join("signed.exe"), &signed).unwrap();

    let config = |sign_body: &str| {
        let sign = tools.template("sign", "echo \"sign|$1\" >> \"$LOG\"; exit 9", &["{path}"]);
        let installer = tools.template("sign_installer", sign_body, &["{path}"]);
        let verify = tools.template(
            "verify",
            "echo \"verify|$(basename \"$1\")\" >> \"$LOG\"",
            &["{path}"],
        );
        format!(
            "\n[codesign.windows]\nsign = {sign}\nsign_installer = {installer}\nverify = {verify}\n"
        )
    };
    let good =
        "echo \"sign_installer|$(basename \"$1\")\" >> \"$LOG\"; cp \"$TOOLS/signed.exe\" \"$1\"";
    let base = fs::read_to_string(&w.config).unwrap();
    let run = |name: &str, body: &str| {
        fs::write(&w.config, format!("{base}{}", config(body))).unwrap();
        let dir = w.dir.path().join(name);
        fs::create_dir(&dir).unwrap();
        let out = dir.join("Hello-Setup.exe");
        let result = w.setup(&out, &[]);
        (dir, out, result)
    };

    let (dir, out, result) = run("signed", good);
    assert_ok(&result, "signed setup");
    assert_eq!(fs::read(&out).unwrap(), signed);
    assert_eq!(
        tools.log(),
        ["sign_installer|Hello-Setup.exe", "verify|Hello-Setup.exe"],
        "the installer's template, not `sign`, then verify"
    );
    // The runtime's own reader finds the trailer before the certificate table.
    let bytes = fs::read(&out).unwrap();
    let located = locate_file(&Bytes(bytes.clone())).unwrap();
    assert_eq!(
        located,
        Located::Setup {
            end: unsigned.len() as u64
        }
    );
    let tail = &bytes[unsigned.len() - TRAILER_SIZE as usize..unsigned.len()];
    let trailer =
        SetupTrailer::parse(tail, unsigned.len() as u64, &Sha256Hasher, &Ed25519Verifier).unwrap();
    assert_eq!(trailer, trailer_of(&unsigned));
    assert_eq!(names_in(&dir), ["Hello-Setup.exe"]);
    assert!(
        stdout(&result).contains("code-sign: Hello-Setup.exe"),
        "{}",
        stdout(&result)
    );

    // Each failure stops `setup` and leaves no file.
    let mut flipped = signed.clone();
    flipped[unsigned.len() - 100] ^= 1;
    fs::write(tools.dir.join("flipped.exe"), &flipped).unwrap();
    let mut grown = signed.clone();
    grown.push(0);
    fs::write(tools.dir.join("grown.exe"), &grown).unwrap();
    for (name, body, expect) in [
        ("nochange", "exit 0", "is not signed after sign_installer"),
        (
            "failing",
            "echo 'the certificate is expired' >&2; exit 7",
            "sign_installer failed",
        ),
        ("damaged", "cp \"$TOOLS/flipped.exe\" \"$1\"", "setup"),
        (
            "grown",
            "cp \"$TOOLS/grown.exe\" \"$1\"",
            "not read back as a setup file",
        ),
    ] {
        let (dir, out, result) = run(name, body);
        let err = assert_fails(&result, 1, name);
        assert!(err.contains(expect), "{name}: {err}");
        assert!(!out.exists(), "{name}: an output file was left");
        assert!(names_in(&dir).is_empty(), "{name}: {:?}", names_in(&dir));
    }
}

/// A Linux setup file and a macOS `.zip` are not signed: no template runs for them.
#[test]
fn linux_setup_and_the_zip_run_no_signing_tool() {
    let w = World::new();
    let tools = Tools::new(&w);
    let windows = tools.template("sign", "echo \"sign|$1\" >> \"$LOG\"", &["{path}"]);
    append_config(&w, &format!("\n[codesign.windows]\nsign = {windows}\n"));
    assert_ok(
        &w.setup(&w.dir.path().join("linux-setup"), &[]),
        "linux setup",
    );
    assert!(tools.log().is_empty(), "{:?}", tools.log());

    let m = World::mac(PLAIN_MAC);
    let tools = Tools::new(&m);
    append_config(&m, &tools.macos_section(&[]));
    assert_ok(&mac_zip(&m, &m.dir.path().join("a.zip")), "setup --zip");
    assert!(
        tools.log().is_empty(),
        "the zip holds the released bundle: {:?}",
        tools.log()
    );
}

/// The installer app is signed (its runtime, then the app), verified, notarized and stapled before
/// the image is built; then the image is signed, notarized and stapled (M9-D5). The recording shows
/// the order, and the zip handed to the notary holds the installer app.
#[test]
fn macos_dmg_signing_runs_in_the_fixed_order() {
    if !macos_host("the installer .dmg") {
        return;
    }
    let w = World::mac(PLAIN_MAC);
    let tools = Tools::new(&w);
    append_config(&w, &tools.macos_section(&[]));
    let dir = w.dir.path().join("out");
    fs::create_dir(&dir).unwrap();
    let dmg = dir.join("hello.dmg");
    let out = mac_dmg(&w, &dmg);
    assert_ok(&out, "setup with signing");
    assert_eq!(
        tools.log(),
        [
            "sign_installer|lunepack-runtime",
            "sign_installer|Install Hello.app",
            "verify|Install Hello.app",
            "notarize|Install Hello.app|lunepack-notarize.zip",
            "staple|Install Hello.app",
            "sign_installer|installer.dmg",
            "notarize|installer.dmg|installer.dmg",
            "staple|installer.dmg",
        ]
    );
    let zip = fs::read(tools.dir.join("notarized-app.zip")).unwrap();
    for name in [
        "Install Hello.app/Contents/MacOS/lunepack-ui",
        "Install Hello.app/Contents/_CodeSignature/CodeResources",
    ] {
        assert!(
            zip.windows(name.len()).any(|w| w == name.as_bytes()),
            "{name}"
        );
    }
    // The image is signed (the dispatching tool ran the real `codesign`, ad hoc) and holds the
    // stapled, sealed app.
    let signed = std::process::Command::new("/usr/bin/codesign")
        .args(["--verify"])
        .arg(&dmg)
        .output()
        .unwrap();
    assert!(
        signed.status.success(),
        "{}",
        String::from_utf8_lossy(&signed.stderr)
    );
    let mount = attach(&dmg, &w.dir.path().join("mnt"));
    let app = mount.0.join("Install Hello.app");
    assert_eq!(
        fs::read(app.join("Contents/CodeResources")).unwrap(),
        b"ticket\n"
    );
    assert!(app.join("Contents/_CodeSignature/CodeResources").is_file());
    assert_eq!(
        fs::read(app.join("Contents/MacOS/lunepack-runtime")).unwrap(),
        signed_macho()
    );
    assert_eq!(names_in(&dir), ["hello.dmg"]);
}

/// Every step of the installer signing that fails stops `setup`, with the message shape of M9-D3,
/// and leaves no file at the final name and nothing beside it.
#[test]
fn a_failing_signing_step_leaves_no_dmg() {
    if !macos_host("the installer .dmg") {
        return;
    }
    let dispatch = |app: &str, dmg: &str, runtime: &str| {
        format!(
            "echo \"sign_installer|$(basename \"$1\")\" >> \"$LOG\"\n\
             case \"$1\" in\n\
             *.dmg) {dmg} ;;\n\
             *.app) {app} ;;\n\
             *) {runtime} ;;\n\
             esac"
        )
    };
    let seal = "mkdir -p \"$1/Contents/_CodeSignature\"; echo seal > \"$1/Contents/_CodeSignature/CodeResources\"";
    let real = "/usr/bin/codesign --force --sign - \"$1\"";
    let cp = "cp \"$TOOLS/signed.macho\" \"$1\"";
    type Case<'a> = (&'a str, Vec<(&'a str, String)>, &'a str);
    let cases: Vec<Case> = vec![
        (
            "the runtime is not signed",
            vec![("sign_installer", dispatch(seal, real, "echo 'bad key' >&2; exit 3"))],
            "sign_installer failed",
        ),
        (
            "the app is left unsigned",
            vec![("sign_installer", dispatch("exit 0", real, cp))],
            "Install Hello.app is not signed after sign_installer",
        ),
        (
            "verify fails",
            vec![("verify", "exit 4".to_owned())],
            "verify failed",
        ),
        (
            "the app's notarization fails",
            vec![("notarize", "echo 'rejected' >&2; exit 5".to_owned())],
            "notarize failed",
        ),
        (
            "the app's staple leaves no ticket",
            vec![("staple", "exit 0".to_owned())],
            "staple left no ticket",
        ),
        (
            "the image is left unsigned",
            vec![("sign_installer", dispatch(seal, "exit 0", cp))],
            "hello.dmg is not signed after sign_installer",
        ),
        (
            "the image's notarization fails",
            vec![("notarize", "case \"$1\" in *.dmg) exit 5;; esac".to_owned())],
            "notarize failed",
        ),
        (
            "the image's staple fails",
            vec![(
                "staple",
                "case \"$1\" in *.dmg) exit 6;; *) echo ticket > \"$1/Contents/CodeResources\";; esac"
                    .to_owned(),
            )],
            "staple failed",
        ),
    ];
    for (what, over, expect) in cases {
        let w = World::mac(PLAIN_MAC);
        let tools = Tools::new(&w);
        let over: Vec<(&str, &str)> = over.iter().map(|(k, b)| (*k, b.as_str())).collect();
        append_config(&w, &tools.macos_section(&over));
        let dir = w.dir.path().join("out");
        fs::create_dir(&dir).unwrap();
        let dmg = dir.join("hello.dmg");
        let err = assert_fails(&mac_dmg(&w, &dmg), 1, what);
        assert!(err.contains(expect), "{what}: {err}");
        assert!(err.contains("code-sign:"), "{what}: {err}");
        assert!(!dmg.exists(), "{what}: an image was left");
        assert!(names_in(&dir).is_empty(), "{what}: {:?}", names_in(&dir));
    }
}

/// Real `codesign`, ad hoc: the installer app inside the image passes `codesign --verify --deep
/// --strict` after mounting, and so does the image; without `[codesign.macos]` the same app does
/// not (the instrument).
#[test]
fn the_installer_app_in_the_dmg_verifies_when_signed_and_not_otherwise() {
    if !macos_host("the signed installer .dmg") {
        return;
    }
    let w = World::mac(Mac {
        ui: true,
        icon: true,
        signed: true,
        service: false,
    });
    let verify = |dmg: &Path, mnt: &str| {
        let mount = attach(dmg, &w.dir.path().join(mnt));
        let app = mount.0.join("Install Hello.app");
        let out = std::process::Command::new("/usr/bin/codesign")
            .args(["--verify", "--deep", "--strict"])
            .arg(&app)
            .output()
            .unwrap();
        (
            out.status.success(),
            String::from_utf8_lossy(&out.stderr).into_owned(),
        )
    };
    let plain = w.dir.path().join("plain.dmg");
    assert_ok(&mac_dmg(&w, &plain), "setup without signing");
    assert!(
        !verify(&plain, "mnt-plain").0,
        "the instrument: an unsigned installer app must not verify"
    );

    append_config(
        &w,
        "\n[codesign.macos]\n\
         sign = ['/usr/bin/codesign', '--force', '--sign', '-', '{path}']\n\
         sign_installer = ['/usr/bin/codesign', '--force', '--sign', '-', '{path}']\n\
         verify = ['/usr/bin/codesign', '--verify', '--deep', '--strict', '{path}']\n",
    );
    let signed = w.dir.path().join("signed.dmg");
    let out = mac_dmg(&w, &signed);
    assert_ok(&out, "setup with ad-hoc signing");
    let (ok, why) = verify(&signed, "mnt-signed");
    assert!(ok, "the installer app does not verify: {why}");
    let image = std::process::Command::new("/usr/bin/codesign")
        .arg("--verify")
        .arg(&signed)
        .output()
        .unwrap();
    assert!(image.status.success(), "the image is not signed");
}

// ---- The setup anchor (M10-D4, M10 step 14) -------------------------------------------------

/// The anchor of a built Windows setup file, read through its image's `RT_RCDATA` resource, and
/// that resource's byte span.
fn anchor_of(bytes: &[u8]) -> (lunepack_core::setup::SetupAnchor, std::ops::Range<usize>) {
    use lunepack_core::setup::{ANCHOR_RESOURCE_ID, SetupAnchor};
    let span = lunepack_core::pe::rcdata(bytes, ANCHOR_RESOURCE_ID)
        .unwrap()
        .expect("an anchor resource");
    let range = span.file_offset as usize..span.file_offset as usize + span.len as usize;
    (SetupAnchor::parse(&bytes[range.clone()]).unwrap(), range)
}

/// Verifies `bytes` against the anchor in its own image, as a started Setup.exe does.
fn check_anchored(bytes: &[u8]) -> Result<u64, String> {
    let (anchor, _) = anchor_of(bytes);
    let end = bytes.len();
    lunepack_core::setup::verify_setup_anchored(
        &anchor,
        &bytes[end - TRAILER_SIZE as usize..],
        &Bytes(bytes.to_vec()),
        end as u64,
        &ClockReading::read(&At(AT), None),
        &LzmaCodec,
        &Sha256Hasher,
        &Ed25519Verifier,
    )
    .map(|a| a.keyset_version)
    .map_err(|e| e.to_string())
}

#[test]
fn windows_setup_carries_its_own_anchor_and_only_the_anchor_was_patched() {
    use lunepack_core::Hasher as _;
    use lunepack_core::setup::{ANCHOR_SIZE, SetupAnchor};
    let w = World::windows(plain_windows());
    let a = w.dir.path().join("a.exe");
    assert_ok(&w.setup(&a, &[]), "windows setup");
    let bytes = fs::read(&a).unwrap();
    // Deterministic: a second run to the same file name gives the same bytes.
    let again = w.dir.path().join("again").join("a.exe");
    fs::create_dir_all(again.parent().unwrap()).unwrap();
    assert_ok(&w.setup(&again, &[]), "windows setup again");
    assert_eq!(fs::read(&again).unwrap(), bytes, "two runs differ");

    // The anchor equals the digests of the file's own trailer block, key set and manifest.
    let t = trailer_of(&bytes);
    let part = |p: lunepack_core::setup::SetupPart| {
        bytes[p.offset as usize..(p.offset + p.length) as usize].to_vec()
    };
    let (anchor, span) = anchor_of(&bytes);
    assert_eq!(span.len(), ANCHOR_SIZE);
    assert!(
        span.end <= t.keys.offset as usize,
        "inside the runtime image"
    );
    let h = Sha256Hasher;
    assert_eq!(
        anchor.trailer,
        h.sha256(&bytes[bytes.len() - TRAILER_SIZE as usize..])
    );
    assert_eq!(anchor.keys, h.sha256(&part(t.keys)));
    assert_eq!(anchor.manifest, h.sha256(&part(t.manifest)));
    assert!(!anchor.is_placeholder());
    assert_eq!(check_anchored(&bytes), Ok(1));

    // With the placeholder put back, the runtime image is the stamped one: its RT_RCDATA 1 is the
    // placeholder, it still passes the runtime check, and nothing else differs.
    let mut placeholder = bytes.clone();
    placeholder[span.clone()].copy_from_slice(&SetupAnchor::PLACEHOLDER);
    let differing: Vec<usize> = (0..bytes.len())
        .filter(|&i| bytes[i] != placeholder[i])
        .collect();
    assert!(!differing.is_empty());
    assert!(differing.iter().all(|i| span.contains(i)));
    let runtime = &placeholder[..t.keys.offset as usize];
    lunepack_core::check_runtime_image(runtime, lunepack_core::Target::WindowsX86_64)
        .expect("a hardened Windows runtime");
    let image = editpe::Image::parse(runtime.to_vec()).unwrap();
    let rcdata = image
        .resource_directory()
        .unwrap()
        .root()
        .get(editpe::ResourceEntryName::ID(10))
        .and_then(|e| e.as_table())
        .and_then(|t| t.get(editpe::ResourceEntryName::ID(1)))
        .and_then(|e| e.as_table())
        .expect("RT_RCDATA 1");
    let langs = rcdata.entries();
    assert_eq!(langs.len(), 1);
    let data = rcdata.get(langs[0]).and_then(|e| e.as_data()).unwrap();
    assert_eq!(data.data(), &SetupAnchor::PLACEHOLDER[..]);
    // The placeholder file is refused.
    assert!(check_anchored(&placeholder).is_err());
}

#[test]
fn a_flipped_byte_in_the_trailer_keys_or_manifest_fails_the_anchored_read_back() {
    let w = World::windows(plain_windows());
    let a = w.dir.path().join("a.exe");
    assert_ok(&w.setup(&a, &[]), "windows setup");
    let bytes = fs::read(&a).unwrap();
    let t = trailer_of(&bytes);
    for (name, at) in [
        ("trailer", bytes.len() - TRAILER_SIZE as usize + 3),
        ("key set", (t.keys.offset + t.keys.length / 2) as usize),
        (
            "manifest",
            (t.manifest.offset + t.manifest.length / 2) as usize,
        ),
    ] {
        let mut b = bytes.clone();
        b[at] ^= 0x01;
        let err = check_anchored(&b).unwrap_err();
        assert!(err.contains(name), "{name}: {err}");
    }
    // A flipped anchor byte fails too.
    let (_, span) = anchor_of(&bytes);
    let mut b = bytes.clone();
    b[span.start + 20] ^= 0x01;
    assert!(check_anchored(&b).is_err());
}

#[test]
fn a_linux_setup_file_has_no_anchor() {
    let w = World::new();
    let a = w.dir.path().join("a-setup");
    assert_ok(&w.setup(&a, &[]), "setup");
    let bytes = fs::read(&a).unwrap();
    let t = trailer_of(&bytes);
    assert_eq!(&bytes[..w.runtime.len()], &w.runtime[..]);
    assert!(
        bytes[w.runtime.len()..t.keys.offset as usize]
            .iter()
            .all(|&b| b == 0)
    );
}

// ---- the all-users `.pkg` of a macOS release with the service (M11 step 7) -----------------------

const SERVICE_MAC: Mac = Mac {
    ui: true,
    icon: true,
    signed: false,
    service: true,
};

/// The payload folder of the package below `/` (M11-D8).
const PKG_LEAF: &str = "Library/Application Support/lunepack/.installer/org.example.hello";

/// Runs a system tool and returns its output; the tool must exist (macOS).
fn system(program: &str, args: &[&std::ffi::OsStr]) -> Output {
    std::process::Command::new(program)
        .args(args)
        .output()
        .unwrap_or_else(|e| panic!("{program}: {e}"))
}

/// The mode, owner, group and path of each entry of the BOM at `bom`, from `lsbom -p MUGf`.
fn bom_entries(bom: &Path) -> Vec<(String, String, String, String)> {
    let out = system(
        "/usr/bin/lsbom",
        &["-p".as_ref(), "MUGf".as_ref(), bom.as_os_str()],
    );
    assert!(out.status.success(), "lsbom: {}", stderr(&out));
    stdout(&out)
        .lines()
        .map(|line| {
            let f: Vec<&str> = line.split('\t').collect();
            assert_eq!(f.len(), 4, "an lsbom line: {line:?}");
            (
                f[0].trim().to_owned(),
                f[1].to_owned(),
                f[2].to_owned(),
                f[3].to_owned(),
            )
        })
        .collect()
}

/// A release with the service builds `<name>.pkg` beside the image and embeds the same bytes in the
/// installer app. The package holds exactly the runtime and the payload file under the root-only
/// `.installer/<app id>` folder, every folder above `.installer` is root 0755, nothing is group- or
/// world-writable, the postinstall is the fixed line, and the distribution allows the local system
/// domain only (M11-D8, P4).
#[test]
fn macos_pkg_holds_exactly_the_runtime_and_the_payload_in_root_only_folders() {
    let w = World::mac(SERVICE_MAC);
    let dir = w.dir.path().join("out");
    fs::create_dir(&dir).unwrap();
    let dmg = dir.join("hello.dmg");
    if !macos_host("the all-users .pkg") {
        let err = assert_fails(&mac_dmg(&w, &dmg), 1, "dmg off macOS");
        assert!(err.contains("--zip"), "{err}");
        assert!(names_in(&dir).is_empty(), "{:?}", names_in(&dir));
        return;
    }
    let out = mac_dmg(&w, &dmg);
    assert_ok(&out, "setup of a release with the service");
    let said: Vec<String> = stdout(&out).lines().map(str::to_owned).collect();
    assert!(said[0].starts_with("setup: hello.dmg ("), "{said:?}");
    assert!(said[1].starts_with("setup: hello.pkg ("), "{said:?}");
    assert_eq!(names_in(&dir), ["hello.dmg", "hello.pkg"]);
    let pkg = dir.join("hello.pkg");

    // Unsigned: pkgutil says so, and setup still succeeded (no [codesign.macos]).
    let sig = system(
        "/usr/sbin/pkgutil",
        &["--check-signature".as_ref(), pkg.as_os_str()],
    );
    assert!(!sig.status.success());
    assert!(stdout(&sig).contains("no signature"), "{}", stdout(&sig));

    // The payload files, exactly.
    let listed = system(
        "/usr/sbin/pkgutil",
        &["--payload-files".as_ref(), pkg.as_os_str()],
    );
    assert_ok(&listed, "pkgutil --payload-files");
    let mut files: Vec<String> = stdout(&listed).lines().map(str::to_owned).collect();
    files.sort();
    let mut want: Vec<String> = [
        ".",
        "./Library",
        "./Library/Application Support",
        "./Library/Application Support/lunepack",
        "./Library/Application Support/lunepack/.installer",
        &format!("./{PKG_LEAF}"),
        &format!("./{PKG_LEAF}/lunepack-runtime"),
        &format!("./{PKG_LEAF}/lunepack-setup.payload"),
    ]
    .iter()
    .map(|s| (*s).to_owned())
    .collect();
    want.sort();
    assert_eq!(files, want);

    // Expanded: the distribution, the component's identifier, the scripts, the modes in the BOM.
    let expanded = w.dir.path().join("expanded");
    let ex = system(
        "/usr/sbin/pkgutil",
        &[
            "--expand-full".as_ref(),
            pkg.as_os_str(),
            expanded.as_os_str(),
        ],
    );
    assert_ok(&ex, "pkgutil --expand-full");
    let distribution = fs::read_to_string(expanded.join("Distribution")).unwrap();
    assert!(
        distribution.contains(
            "<domains enable_localSystem=\"true\" enable_currentUserHome=\"false\" enable_anywhere=\"false\"/>"
        ),
        "{distribution}"
    );
    assert!(
        distribution.contains("<title>Hello</title>"),
        "{distribution}"
    );
    assert!(
        distribution.contains("<os-version min=\"10.15\"/>"),
        "{distribution}"
    );
    let component = expanded.join("component.pkg");
    let info = fs::read_to_string(component.join("PackageInfo")).unwrap();
    for needle in [
        "identifier=\"org.example.hello.lunepack-machine\"",
        "version=\"1.2.3\"",
        "install-location=\"/\"",
    ] {
        assert!(info.contains(needle), "{needle}\n{info}");
    }
    assert_eq!(
        fs::read(component.join("Scripts/postinstall")).unwrap(),
        b"#!/bin/sh\nexec \"/Library/Application Support/lunepack/.installer/org.example.hello/lunepack-runtime\" machine-install --pkg\n"
    );
    assert_eq!(names_in(&component.join("Scripts")), ["postinstall"]);
    assert_eq!(
        fs::metadata(component.join("Scripts/postinstall"))
            .unwrap()
            .permissions()
            .mode()
            & 0o777,
        0o755
    );

    let entries = bom_entries(&component.join("Bom"));
    let group = entries[0].2.clone();
    let mut seen = Vec::new();
    for (mode, user, grp, path) in &entries {
        assert_eq!(user, "root", "{path}");
        assert_eq!(grp, &group, "one recorded group: {path}");
        let bits = &mode[1..];
        assert_eq!(&bits[4..5], "-", "group-writable: {path} {mode}");
        assert_eq!(&bits[7..8], "-", "world-writable: {path} {mode}");
        let expect = match path.as_str() {
            "."
            | "./Library"
            | "./Library/Application Support"
            | "./Library/Application Support/lunepack" => "drwxr-xr-x",
            "./Library/Application Support/lunepack/.installer" => "drwx------",
            p if p == format!("./{PKG_LEAF}") => "drwx------",
            p if p.ends_with("/lunepack-runtime") => "-rwx------",
            p if p.ends_with("/lunepack-setup.payload") => "-rw-------",
            other => panic!("an entry the package must not hold: {other}"),
        };
        assert_eq!(mode, expect, "{path}");
        seen.push(path.clone());
    }
    assert_eq!(seen.len(), 8, "{seen:?}");

    // The files are the release's own runtime and payload (read through its signed frames), and the
    // installer app embeds the same package and the same payload.
    let leaf = component.join("Payload").join(PKG_LEAF);
    assert_eq!(
        fs::read(leaf.join("lunepack-runtime")).unwrap(),
        mac_binary(false)
    );
    let mount = attach(&dmg, &w.dir.path().join("mnt"));
    let app = mount.0.join("Install Hello.app");
    assert_eq!(
        fs::read(leaf.join("lunepack-setup.payload")).unwrap(),
        fs::read(app.join("Contents/Resources/lunepack-setup.payload")).unwrap()
    );
    assert_eq!(
        fs::read(app.join("Contents/Resources/lunepack-all-users.pkg")).unwrap(),
        fs::read(&pkg).unwrap()
    );
}

